---@alias gcp.dataflow_v1b3.SourceSplitShardDerivationModeEnum "SOURCE_DERIVATION_MODE_UNKNOWN"|"SOURCE_DERIVATION_MODE_INDEPENDENT"|"SOURCE_DERIVATION_MODE_CHILD_OF_CURRENT"|"SOURCE_DERIVATION_MODE_SIBLING_OF_CURRENT"

---@alias gcp.dataflow_v1b3.SourceSplitShardList gcp.dataflow_v1b3.SourceSplitShard[]

